<?php
declare(strict_types=1);
require_once ROOT.'/app/Core/RecordWorkspace.php';
final class StudyService extends RecordWorkspace {
    protected const TABLE='study_records';
    public static function save(string $kind,array $input,?int $id=null,bool $transaction=true):int{return $transaction?Db::tx(fn()=>parent::save($kind,$input,$id)):parent::save($kind,$input,$id);}
    public static function catalog():array{return [
        'attendance'=>['Attendance',['module_id'=>'int:1:99999999','date'=>'date','state'=>'enum:present,absent,excused','warning_below'=>'int:0:100']],
        'grade_thresholds'=>['Institution grade thresholds',['grade'=>'text','minimum_mark'=>'decimal','maximum_mark'=>'decimal','grade_points'=>'decimal','source'=>'text']],
        'gpa_scenarios'=>['Per-module GPA scenarios',['module_id'=>'int:1:99999999','expected_mark'=>'decimal']],
        'assignment_plans'=>['Assignment backward plans',['assignment_id'=>'int:1:99999999','title'=>'text','starts'=>'date','due'=>'date','steps'=>'int:1:30','total_minutes'=>'int:5:14400']],
        'exam_plans'=>['Exam revision plans',['exam_id'=>'int:1:99999999','title'=>'text','starts'=>'date','ends'=>'date','topics'=>'text','minutes_per_day'=>'int:5:480','topic_minutes'=>'int:5:480']],
        'decks'=>['Flashcard decks',['title'=>'text','module_id'=>'int:1:99999999']],
        'cards'=>['Spaced-repetition cards',['deck'=>'ref:decks','question'=>'text','answer'=>'text']],
        'notes'=>['Module notes',['title'=>'text','module_id'=>'int:1:99999999','tags'=>'?text','markdown'=>'text']],
        'references'=>['APA / Harvard references',['source_type'=>'enum:book,journal,web','author'=>'text','year'=>'int:1500:2100','title'=>'text','publisher'=>'text','journal'=>'?text','volume'=>'?text','issue'=>'?text','pages'=>'?text','doi'=>'?text','url'=>'?url','accessed'=>'?date']],
        'groups'=>['Group projects',['title'=>'text','module_id'=>'int:1:99999999','work_project_id'=>'?int:1:99999999']],
        'contributions'=>['Member contributions',['project'=>'ref:groups','person'=>'text','date'=>'date','minutes'=>'int:1:1440','outcome'=>'text','evidence'=>'?url']],
        'papers'=>['Past papers & mistakes',['title'=>'text','module_id'=>'int:1:99999999','attempted'=>'date','score'=>'decimal','maximum'=>'decimal','topic'=>'text','mistake'=>'text','correction'=>'text']],
        'thesis'=>['Thesis milestones',['title'=>'text','due'=>'date','state'=>'enum:planned,in_progress,complete','evidence'=>'?url']],
        'supervision'=>['Supervisor meetings',['title'=>'text','date'=>'date','supervisor'=>'text','notes'=>'text','next_action'=>'?text','next_due'=>'?date']],
        'placements'=>['Internships / placements',['company'=>'text','role'=>'text','starts'=>'date','ends'=>'date','state'=>'enum:applied,interview,offered,active,complete,rejected','evidence'=>'?url']],
        'portfolio'=>['CV & portfolio evidence',['kind'=>'enum:skill,project,certificate,course','title'=>'text','summary'=>'text','evidence'=>'?url']],
        'fee_plans'=>['Academic fees',['title'=>'text','total'=>'money','due'=>'date','notes'=>'?text']],
        'instalments'=>['Fee instalments',['plan'=>'ref:fee_plans','amount'=>'money','due'=>'date','paid_on'=>'?date']],
        'scholarships'=>['Scholarships',['title'=>'text','amount'=>'money0','deadline'=>'date','state'=>'enum:preparing,applied,awarded,rejected','requirements'=>'text']],
        'library'=>['Library loans',['book'=>'text','borrowed'=>'date','due'=>'date','returned'=>'?date','renewals'=>'int:0:99']],
    ];}
    protected static function validate(string $kind,array $d,?int $id):array{
        if(isset($d['module_id'])&&!Db::one('SELECT id FROM uni_modules WHERE id=?',[$d['module_id']]))throw new InvalidArgumentException(t('Choose an existing University module ID.'));
        if(isset($d['starts'],$d['ends']))self::dateRange($d['starts'],$d['ends']);if(isset($d['starts'],$d['due']))self::dateRange($d['starts'],$d['due']);if(isset($d['borrowed'],$d['due']))self::dateRange($d['borrowed'],$d['due']);if(isset($d['returned'])&&$d['returned']<$d['borrowed'])throw new InvalidArgumentException(t('Return date cannot precede borrowing.'));
        if($kind==='attendance')foreach(self::rows($kind)as $r)if($r['id']!==$id&&$r['fields']['module_id']===$d['module_id']&&$r['fields']['date']===$d['date'])throw new InvalidArgumentException(t('Attendance is already recorded for this module/date.'));
        if($kind==='grade_thresholds'){if($d['minimum_mark']>$d['maximum_mark']||$d['maximum_mark']>100||$d['grade_points']>10)throw new InvalidArgumentException(t('Enter valid mark thresholds and points.'));foreach(self::rows($kind)as $r)if($r['id']!==$id&&max($r['fields']['minimum_mark'],$d['minimum_mark'])<=min($r['fields']['maximum_mark'],$d['maximum_mark']))throw new InvalidArgumentException(t('Grade mark bands must not overlap.'));}
        if($kind==='gpa_scenarios'){if($d['expected_mark']>100)throw new InvalidArgumentException(t('Marks must be from zero to 100.'));foreach(self::rows($kind)as $r)if($r['id']!==$id&&$r['fields']['module_id']===$d['module_id'])throw new InvalidArgumentException(t('Edit the existing scenario for this module.'));}
        if($kind==='assignment_plans'){$assignment=Db::one('SELECT id,due_date FROM assignments WHERE id=?',[$d['assignment_id']]);if(!$assignment||$assignment['due_date']&&$d['due']>$assignment['due_date'])throw new InvalidArgumentException(t('Choose an assignment and plan to finish by its deadline.'));if($d['total_minutes']<$d['steps']*5||$d['total_minutes']>$d['steps']*480)throw new InvalidArgumentException(t('Each generated step needs 5–480 estimated minutes.'));}
        if($kind==='exam_plans'){ $exam=Db::one('SELECT * FROM exams WHERE id=?',[$d['exam_id']]);if(!$exam||$d['ends']>$exam['date'])throw new InvalidArgumentException(t('Choose an existing exam and finish revision by its date.'));}
        if($kind==='papers'&&($d['maximum']<=0||$d['score']>$d['maximum']))throw new InvalidArgumentException(t('Score cannot exceed the positive maximum.'));
        if($kind==='instalments'){$plan=self::get($d['plan'],'fee_plans')['fields'];$total=$d['amount'];foreach(self::rows('instalments')as $r)if($r['id']!==$id&&$r['fields']['plan']===$d['plan'])$total+=$r['fields']['amount'];if(round($total*100)>round($plan['total']*100))throw new InvalidArgumentException(t('Instalments exceed the fee-plan total.'));}
        if($kind==='groups'&&$d['work_project_id']!==null&&!Db::one('SELECT id FROM work_projects WHERE id=?',[$d['work_project_id']]))throw new InvalidArgumentException(t('Choose an existing Work project.'));return $d;
    }
    public static function attendance():array{$out=[];foreach(self::rows('attendance')as $r){$d=$r['fields'];$id=$d['module_id'];$out[$id]??=['present'=>0,'count'=>0,'threshold'=>$d['warning_below']];if($d['state']!=='excused'){$out[$id]['count']++;if($d['state']==='present')$out[$id]['present']++;}}foreach($out as &$v)$v['percent']=$v['count']?round($v['present']/$v['count']*100,1):null;return $out;}
    public static function clashes():array{$rows=Db::all('SELECT * FROM timetable ORDER BY day,start_time');$out=[];foreach($rows as $i=>$a)foreach(array_slice($rows,$i+1)as $b)if($a['day']===$b['day']&&max($a['start_time'],$b['start_time'])<min($a['end_time'],$b['end_time']))$out[]=[$a,$b];return $out;}
    public static function scenario():array{$points=0;$credits=0;$unknown=[];$predictions=[];foreach(self::rows('gpa_scenarios')as $r)$predictions[$r['fields']['module_id']]=$r['fields']['expected_mark'];foreach(Db::all('SELECT * FROM uni_modules')as $m){$credit=(int)$m['credits'];if(!$credit)continue;$gp=null;if(isset($predictions[$m['id']])){foreach(self::rows('grade_thresholds')as $band){$d=$band['fields'];if($predictions[$m['id']]>=$d['minimum_mark']&&$predictions[$m['id']]<=$d['maximum_mark'])$gp=$d['grade_points'];}}else $gp=UniService::points()[$m['grade']]??null;if($gp===null){$unknown[]=$m['name'];continue;}$points+=$gp*$credit;$credits+=$credit;}return ['gpa'=>$credits?round($points/$credits,2):null,'credits'=>$credits,'unknown'=>$unknown];}
    public static function generate(string $kind,int $id):int{$r=self::get($id,$kind);$d=$r['fields'];$items=[];if($kind==='assignment_plans'){$days=(int)(new DateTimeImmutable($d['starts']))->diff(new DateTimeImmutable($d['due']))->format('%a');for($i=1;$i<=$d['steps'];$i++)$items[]=['estimate_minutes'=>(int)floor(($d['total_minutes']??($d['steps']*30))/$d['steps'])+($i<=($d['total_minutes']??0)%$d['steps']?1:0),'title'=>$d['title'].' · step '.$i,'due'=>(new DateTimeImmutable($d['starts']))->modify('+'.(int)floor($days*$i/$d['steps']).' days')->format('Y-m-d')];}elseif($kind==='exam_plans'){$topics=array_values(array_filter(array_map('trim',preg_split('/\R/',$d['topics']))));if(!$topics||count($topics)>200)throw new InvalidArgumentException(t('Enter 1–200 topics, one per line.'));$days=(int)(new DateTimeImmutable($d['starts']))->diff(new DateTimeImmutable($d['ends']))->format('%a')+1;$effort=$d['topic_minutes']??min(30,$d['minutes_per_day']);$slots=(int)floor($d['minutes_per_day']/$effort);if($slots<1||count($topics)>$days*$slots)throw new InvalidArgumentException(t('Not enough daily revision time for these topics. Extend the plan or reduce topic effort.'));foreach($topics as $i=>$topic)$items[]=['estimate_minutes'=>$effort,'title'=>$d['title'].' · '.$topic,'due'=>(new DateTimeImmutable($d['starts']))->modify('+'.(int)floor($i/$slots).' days')->format('Y-m-d')];}else throw new InvalidArgumentException(t('Choose an assignment or exam plan.'));return Db::tx(function()use($id,$kind,$items){$count=0;foreach($items as $i=>$task){$key=$kind.':'.$id.':'.$i;if(Db::one('SELECT identity FROM study_generated_tasks WHERE identity=?',[$key]))continue;$taskId=PlannerService::saveTask(null,$task);Db::run('INSERT INTO study_generated_tasks(identity,task_id) VALUES(?,?)',[$key,$taskId]);$count++;}return $count;});}
    public static function review(int $id,string $rating,string $date):void{self::get($id,'cards');valid_date($date);if(!in_array($rating,['again','good','easy'],true))throw new InvalidArgumentException(t('Choose a review result.'));if($date!==date('Y-m-d'))throw new InvalidArgumentException(t('Reviews use today\'s date.'));if(Db::one('SELECT id FROM study_card_reviews WHERE card_id=? AND reviewed_on=?',[$id,$date]))throw new InvalidArgumentException(t('This card has been reviewed today.'));$last=Db::one('SELECT * FROM study_card_reviews WHERE card_id=? ORDER BY id DESC LIMIT 1',[$id]);if($last&&$last['next_on']>$date)throw new InvalidArgumentException(t('This card is not due yet.'));$n=(int)Db::one('SELECT COUNT(*) n FROM study_card_reviews WHERE card_id=?',[$id])['n'];$interval=$rating==='again'?1:($rating==='easy'?min(60,7*($n+1)):min(30,[1,3,7,14,30][min($n,4)]));Db::run('INSERT INTO study_card_reviews(card_id,reviewed_on,rating,next_on) VALUES(?,?,?,?)',[$id,$date,$rating,date('Y-m-d',strtotime($date.' +'.$interval.' days'))]);}
    public static function citation(array $d,string $style):string{$author=rtrim($d['author'],'.');$type=$d['source_type']??'book';$base=$author.($style==='harvard'?' (':'. (').$d['year'].($style==='harvard'?') ':'). ').$d['title'].'. ';if($type==='journal'){$base.=($d['journal']??'').(!empty($d['volume'])?', '.$d['volume']:'').(!empty($d['issue'])?'('.$d['issue'].')':'').(!empty($d['pages'])?', '.$d['pages']:'').'.';}else $base.=$d['publisher'].'.';$url=!empty($d['doi'])?'https://doi.org/'.$d['doi']:($d['url']??'');return $base.($url?' '.$url:'').($style==='harvard'&&!empty($d['accessed'])?' (Accessed: '.$d['accessed'].').':'');}
    public static function alerts():array{$out=[];$today=date('Y-m-d');foreach(self::rows('library')as $r)if($r['fields']['returned']===null&&$r['fields']['due']<=$today)$out[]=['id'=>hash('sha256','library:'.$r['id'].':'.$today),'title'=>t('Library return due'),'body'=>$r['fields']['book'].' · '.$r['fields']['due'],'route'=>'/study?page=library','level'=>'upcoming'];foreach(self::rows('scholarships')as $r)if(in_array($r['fields']['state'],['preparing','applied'],true)&&$r['fields']['deadline']<=date('Y-m-d',strtotime('+7 days')))$out[]=['id'=>hash('sha256','scholarship:'.$r['id'].':'.$today),'title'=>t('Scholarship deadline'),'body'=>$r['fields']['title'],'route'=>'/study?page=scholarships','level'=>'upcoming'];return $out;}
}
